"""Conservative, non-recursive deletion of proven generated bytecode only."""

import argparse
import hashlib
import importlib.util
import json
import os
import stat
import subprocess
import uuid
from datetime import UTC, datetime
from pathlib import Path

ROOT = Path(__file__).absolute().parents[1]
SCOPES = ("src", "tests", "scripts")
RETAIN = (".venv", ".pytest_cache", ".ruff_cache", "build", "dist", "releases", "backups", "work")


def checked_path(root: Path, path: Path) -> Path:
    """Validate lexical boundary and every existing ancestor without resolving links."""
    root = Path(os.path.abspath(root))
    path = Path(os.path.abspath(path))
    if not path.is_relative_to(root) or path == root:
        raise ValueError(f"Outside cleanup boundary: {path}")
    for part in [*reversed(path.parents), path]:
        try:
            info = part.lstat()
        except FileNotFoundError:
            continue
        if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & 0x400:
            raise ValueError(f"Link/reparse point retained: {part}")
    return path


def git_paths(root: Path, *args: str) -> set[str]:
    result = subprocess.run(["git", "-C", str(root), *args], check=True, capture_output=True)
    return {os.fsdecode(name).replace("\\", "/") for name in result.stdout.split(b"\0") if name}


def fingerprint(path: Path) -> dict:
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
        raise ValueError("Not a single-link regular file")
    return {
        "bytes": info.st_size,
        "mtime_ns": info.st_mtime_ns,
        "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
    }


def plan_cleanup(root: Path) -> dict:
    # Git metadata is read only; no clean/reset or index changes.
    tracked = git_paths(root, "ls-files", "-z", "--cached")
    ignored = git_paths(root, "ls-files", "-z", "--others", "--ignored", "--exclude-standard", "--", *SCOPES)
    plan = {"root": str(root), "candidates": [], "retained": []}

    def retain(path, reason):
        plan["retained"].append({"path": path.relative_to(root).as_posix(), "reason": reason})

    def visit(directory):
        try:
            checked_path(root, directory)
            children = sorted(directory.iterdir())
        except (ValueError, OSError) as exc:
            retain(directory, str(exc))
            return
        for path in children:
            try:
                checked_path(root, path)
                if path.is_dir():
                    visit(path)
                    continue
                if path.parent.name != "__pycache__":
                    continue
                relative = path.relative_to(root).as_posix()
                if relative in tracked or relative not in ignored:
                    raise ValueError("Tracked or not Git-ignored; retained")
                # Only this interpreter's standard cache names for a tracked source.
                source = path.parent.parent / (path.name.split(".")[0] + ".py")
                checked_path(root, source)
                expected = {
                    Path(importlib.util.cache_from_source(str(source), optimization=opt)).name
                    for opt in ("", "1", "2")
                }
                if (source.relative_to(root).as_posix() not in tracked
                        or not source.is_file() or path.name not in expected):
                    raise ValueError("Unknown cache name/source; retained")
                info = fingerprint(path)
                with path.open("rb") as stream:
                    header = stream.read(16)
                if len(header) < 16 or header[:4] != importlib.util.MAGIC_NUMBER:
                    raise ValueError("Unrecognized bytecode header; retained")
                plan["candidates"].append({"path": relative, **info})
            except (ValueError, OSError) as exc:
                retain(path, str(exc))

    for scope in SCOPES:
        if (root / scope).exists():
            visit(root / scope)
    for name in RETAIN:
        path = root / name
        if path.exists() or path.is_symlink():
            retain(path, "Protected environment/archive or review-only output; no recursive deletion")
    return plan


def apply_plan(root: Path, plan: dict) -> list[dict]:
    outcomes = []
    # Rebuild eligibility so staged files, links and regenerated caches are retained.
    current = {entry["path"]: entry for entry in plan_cleanup(root)["candidates"]}
    for entry in plan["candidates"]:
        try:
            relative = Path(entry["path"])
            if (relative.is_absolute() or ".." in relative.parts
                    or relative.parts[0] not in SCOPES or relative.parent.name != "__pycache__"):
                raise ValueError("Invalid cleanup scope")
            path = checked_path(root, root / relative)
            if current.get(entry["path"]) != entry or fingerprint(path) != {
                key: entry[key] for key in ("bytes", "mtime_ns", "sha256")
            }:
                raise ValueError("File or eligibility changed since preview")
            path.unlink()  # Never recursively remove directories.
            outcomes.append({"path": entry["path"], "status": "deleted"})
        except (OSError, ValueError) as exc:
            outcomes.append({"path": entry["path"], "status": "retained", "reason": str(exc)})
    return outcomes


def run_cleanup(root: Path, *, apply: bool = False) -> tuple[Path, dict]:
    plan = plan_cleanup(root)
    plan.update({"mode": "apply" if apply else "dry-run", "timestamp": datetime.now(UTC).isoformat()})
    audit = checked_path(root, root / "work" / "cleanup")
    audit.mkdir(parents=True, exist_ok=True)
    manifest = checked_path(root, audit / f"{datetime.now(UTC):%Y%m%dT%H%M%S}-{uuid.uuid4().hex}.json")
    # Exclusive creation and flush BEFORE deleting anything.
    with manifest.open("x", encoding="utf-8") as stream:
        json.dump(plan, stream, ensure_ascii=False, indent=2)
        stream.flush()
        os.fsync(stream.fileno())
    plan["outcomes"] = apply_plan(root, plan) if apply else []
    result = checked_path(root, manifest.with_suffix(".result.json"))
    with result.open("x", encoding="utf-8") as stream:
        json.dump(plan, stream, ensure_ascii=False, indent=2)
    return result, plan


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true", help="Delete verified bytecode; default is preview")
    args = parser.parse_args()
    manifest, plan = run_cleanup(ROOT, apply=args.apply)
    print(json.dumps({
        "mode": plan["mode"], "candidates": len(plan["candidates"]),
        "deleted": sum(item["status"] == "deleted" for item in plan["outcomes"]),
        "retained_entries": len(plan["retained"]), "manifest": str(manifest),
    }, ensure_ascii=False, indent=2))
    if any(item["status"] == "retained" for item in plan["outcomes"]):
        raise SystemExit(1)


if __name__ == "__main__":
    main()
